using System.Data.Entity; namespace Borodin { public class ModelEF:DbContext { public ModelEF():base("name=ModelEF"){} public DbSet<Users> Users {get;set;} public DbSet<Roles> Roles {get;set;} protected override void OnModelCreating(DbModelBuilder b){b.Entity<Roles>().HasMany(r=>r.Users).WithRequired(u=>u.Roles).HasForeignKey(u=>u.Role_Name).WillCascadeOnDelete(false);} } }
